from fastapi import APIRouter, Depends, HTTPException, Request

router = APIRouter(prefix="/tracking/fleets")

@router.get("/{fleet_id}/active-locations")
async def query_fleet_stream_locations(
    fleet_id: str,
    request: Request,
    current_operator: FleetOperator = Depends(get_current_operator)
):
    if current_operator.fleet_id != fleet_id and not current_operator.is_dispatcher_admin:
        raise HTTPException(status_code=403, detail="Forbidden: operator cannot view real-time coordinates of other fleets")

    faust_app = request.app.state.faust_app
    locations_table = faust_app.tables.get("fleet_live_coordinates")
    if locations_table is None:
        raise HTTPException(status_code=503, detail="Faust table offline")

    fleet_coordinates = locations_table.get(fleet_id)
    if not fleet_coordinates:
        raise HTTPException(status_code=404, detail="No real-time tracking data for fleet")

    return {"fleet_id": fleet_id, "active_units": fleet_coordinates}
